# Create the MINT0/MINT1 grids for the MINT2-only tests (vfold/myLaunch.sh -o)
# of a process directory generated by 'output <procdir> --vfold-with-tests',
# for one folding, with one plain run of vfold/myLaunch.sh (by default in mode
# C/avx2, for all GF channels). The grids are installed (see
# madvfold/test/grids/README for their layout) both:
# - in the codegen source madvfold/test/grids/<proc>/folding_<f1>_<f2>_<f3>[_Delta],
#   which 'output --vfold-with-tests' installs in new process directories
#   (to be committed, after updating madvfold/test/grids/README by hand)
# - in the process directory, <procdir>/vfold/test/grids/folding_<f1>_<f2>_<f3>[_Delta],
#   so that the -o tests use them without regenerating the process directory
# where <proc> is the name used by MadGraph for SubProcesses/P0_<proc> (e.g.
# gg_ttxg for madvfold/DEV/ggttg_vfgen). Existing grids are not removed, they
# are renamed as folding_<f1>_<f2>_<f3>[_Delta].BAK<date>.
# The process must be known to vfold/myLaunch.sh (it has defaults for each
# process). The grids are computed with ENV_VFOLDTEST_MCATNLODELTA=1 if this is set.

set -e
set -o pipefail

usage() {
  echo "Usage:   $0 [--channels '<ch1 ch2...>'] <procdir> <f1,f2,f3>"
  echo "         (default: all GF channels, e.g. --channels '10.0' for GF10.0 only)"
  echo "         (the MINT parameters can be set in the environment, defaults below:"
  echo "         ENV_VFOLDTEST_MINT0_NITERS, ENV_VFOLDTEST_MINT0_NPOINTS, ENV_VFOLDTEST_MINT1_NITERS, ENV_VFOLDTEST_MINT1_NPOINTS)"
  echo "         (also ENV_VFOLD_CUDACPP_BACKEND [avx2], ENV_VFOLD_KPOINT_BATCH, ENV_VFOLDTEST_NEVENTS [10], ENV_VFOLDTEST_ISEED, ENV_VFOLDTEST_MCATNLODELTA)"
  echo "Example: $0 madvfold/DEV/ggttg_vfgen 8,4,1"
  exit 1
}
channels=all
while [ "$1" != "" ]; do
  if [ "$1" == "--channels" ] && [ "$2" != "" ]; then channels=$2; shift 2
  elif [ "${1:0:1}" == "-" ]; then usage
  else break; fi
done
if [ "$1" == "" ] || [ "$2" == "" ] || [ "$3" != "" ]; then usage; fi
if ! [[ "$2" =~ ^[1248],[1248],[1248]$ ]]; then echo "ERROR! Invalid folding '$2' (e.g. 8,4,1 or 1,1,1)"; usage; fi
mg5dir=$(cd $(dirname $0)/../..; pwd -P)
procdir=$(cd $1; pwd -P)
fold=$2
if [ ! -x ${procdir}/vfold/myLaunch.sh ]; then
  echo "ERROR! ${procdir}/vfold/myLaunch.sh not found (generate the process directory with --vfold-with-tests)"
  exit 1
fi

# The name of the process used by MadGraph (as in setupVfoldTests.sh): a single P directory is required
pdirs=$(cd ${procdir}/SubProcesses; for d in P*_*; do if [ -d ${d} ]; then echo ${d}; fi; done)
if [ "$(echo ${pdirs} | wc -w)" != "1" ]; then echo "ERROR! Expected a single SubProcesses/P* directory, found: ${pdirs}"; exit 1; fi
proc=${pdirs#P*_}

# The grids directories
fdir=folding_${fold//,/_}
if [ "${ENV_VFOLDTEST_MCATNLODELTA}" == "1" ]; then fdir=${fdir}_Delta; fi
outs="${mg5dir}/madvfold/test/grids/${proc}/${fdir} ${procdir}/vfold/test/grids/${fdir}"

# Run settings: mode C (by default with avx2), no dumps, kpoint batch as in the tests
# The default MINT parameters are those proposed for ggttg in step 14s (in mode C/avx2,
# estimated from the step 14o grids at about 1 hour for GF10.0 alone at 1,1,1 and 1.5 hours
# at 8,4,1; the channels run in parallel on the available cores): tune them for each process
if [ "${fold}" == "1,1,1" ]; then
  : ${ENV_VFOLD_KPOINT_BATCH:=512}
  : ${ENV_VFOLDTEST_MINT0_NITERS:=10}; : ${ENV_VFOLDTEST_MINT0_NPOINTS:=100000}
  : ${ENV_VFOLDTEST_MINT1_NITERS:=10}; : ${ENV_VFOLDTEST_MINT1_NPOINTS:=400000}
else
  : ${ENV_VFOLD_KPOINT_BATCH:=64}
  : ${ENV_VFOLDTEST_MINT0_NITERS:=10}; : ${ENV_VFOLDTEST_MINT0_NPOINTS:=40000}
  : ${ENV_VFOLDTEST_MINT1_NITERS:=10}; : ${ENV_VFOLDTEST_MINT1_NPOINTS:=40000}
fi
export ENV_VFOLD_KPOINT_BATCH ENV_VFOLDTEST_MINT0_NITERS ENV_VFOLDTEST_MINT0_NPOINTS ENV_VFOLDTEST_MINT1_NITERS ENV_VFOLDTEST_MINT1_NPOINTS
export ENV_VFOLDTEST_MINT0_ACC=-1 # no early stop of MINT0 on accuracy
export ENV_VFOLDTEST_CHANNELS="${channels}" # 'all' is understood by myLaunch.sh
export ENV_FVZ_NDUMP=0 # no extra MINT1 dump iteration (it is included in the MINT1 results and biases them)
export ENV_VFOLD_ME_MODE=C
export ENV_VFOLD_CUDACPP_BACKEND=${ENV_VFOLD_CUDACPP_BACKEND:-avx2}
export ENV_VFOLD_SBORN_GSCALE=1
export ENV_VFOLDTEST_FOLDING=${fold}
export ENV_VFOLDTEST_NEVENTS=${ENV_VFOLDTEST_NEVENTS:-10}
unset ENV_VFOLDTEST_PHYSICS ENV_VFOLDTEST_REQACC # ENV_VFOLDTEST_PHYSICS=1 would ignore the MINT parameters and channels above
echo "INFO: makeGrids.sh procdir=${procdir} proc=${proc} folding=${fold} channels=${channels}"
echo "INFO: MINT0 ${ENV_VFOLDTEST_MINT0_NITERS}x${ENV_VFOLDTEST_MINT0_NPOINTS}, MINT1 ${ENV_VFOLDTEST_MINT1_NITERS}x${ENV_VFOLDTEST_MINT1_NPOINTS}, C/${ENV_VFOLD_CUDACPP_BACKEND}, k${ENV_VFOLD_KPOINT_BATCH}, Delta=${ENV_VFOLDTEST_MCATNLODELTA:-0}"

# The plain run (the log is in the run directory, its stdout in <procdir>/makeGrids_<fdir>.out)
cd ${procdir}
before=$(ls -d Events/run_[0-9]* 2>/dev/null || true)
log=${procdir}/makeGrids_${fdir}.out
echo "INFO: running vfold/myLaunch.sh (stdout in ${log}), started $(date)"
if ! setsid -w ./vfold/myLaunch.sh < /dev/null > ${log} 2>&1; then echo "ERROR! vfold/myLaunch.sh failed, see ${log}"; exit 1; fi
run=$(ls -1trd Events/run_[0-9]* | tail -1)
if [ "${run}" == "" ] || echo "${before}" | grep -qx "${run}"; then echo "ERROR! No new run directory in Events"; exit 1; fi
# (the selected channels only: SubProcesses/P*/GF* may also contain other channels from previous runs)
if [ "${channels}" == "all" ]; then gfs=$(cd ${run}/${pdirs}; ls -d GF* | sort -V); else gfs=$(for c in ${channels}; do echo GF${c}; done); fi
for gf in ${gfs}; do
  for x in res_1.dat mint_grids res_1 grid.MC_integer results.dat; do
    if [ ! -f ${run}/${pdirs}/${gf}/${x} ]; then echo "ERROR! Missing ${run}/${pdirs}/${gf}/${x}"; exit 1; fi
  done
done

# Install the grids in both places (existing grids are renamed, not removed)
bak=BAK$(date +%Y%m%d-%H%M%S)
for out in ${outs}; do
  if [ -e ${out} ]; then mv ${out} ${out}.${bak}; echo "INFO: existing grids renamed as ${out}.${bak}"; fi
  mkdir -p ${out}
  for gf in ${gfs}; do
    mkdir -p ${out}/${pdirs}/${gf}
    for x in res_1.dat mint_grids res_1 grid.MC_integer results.dat; do command cp -p ${run}/${pdirs}/${gf}/${x} ${out}/${pdirs}/${gf}/; done
  done
  command cp -p SubProcesses/job_status.pkl ${run}/LOG.txt ${out}/
  awk '/^ +3 .* # aS /{printf("%g\n",$2)}' Cards/param_card.dat > ${out}/aS.txt
  echo "INFO: grids installed in ${out}"
done

# Summary: per channel, the accumulated ABS integral and integral of the last MINT0/MINT1
# iterations (check that they are stable), the final results (res_1.dat) and their sum
echo "=== Accumulated results of the last 3 iterations of MINT0 and MINT1, and res_1.dat (ABS +- err, integral +- err)"
for gf in ${gfs}; do
  d=${run}/${pdirs}/${gf}
  for m in MINT0 MINT1; do
    awk -v gf=${gf} -v m=${m} '/^ ------- iteration/{it=$3; nrun++} /Not including iteration in results/{nrej++} /Found desired accuracy/{acc=1} /^accumulated results ABS integral /{a=$6" +- "$8} /^accumulated results Integral /{l[++n]=sprintf("%-8s %s iter %3d | ABS %s | Integral %s +- %s",gf,m,it,a,$5,$7)} END{for(i=(n>3?n-2:1);i<=n;i++) print l[i]; printf("%-8s %s iterations: %d run, %d included in the results, %d rejected as large fluctuations%s\n",gf,m,nrun,n,nrej,(acc?" (stopped on accuracy)":"")); if(nrun>n+nrej) printf("%-8s %s WARNING! %d iterations after the first rejected one were not included (stock MINT1: the reset flag is only cleared in MINT0)\n",gf,m,nrun-n-nrej)}' ${d}/log_${m}.txt
  done
  awk -v gf=${gf} '{printf("%-8s res_1.dat     | ABS %.4e +- %.4e | Integral %.4e +- %.4e\n",gf,$1,$2,$3,$4)}' ${d}/res_1.dat
done
for gf in ${gfs}; do cat ${run}/${pdirs}/${gf}/res_1.dat; done | \
  awk '{a+=$1; ea+=$2*$2; i+=$3; ei+=$4*$4} END{printf("SUM      res_1.dat     | ABS %.4e +- %.4e | Integral %.4e +- %.4e\n",a,sqrt(ea),i,sqrt(ei))}'
grep ELAPSED ${run}/LOG.txt
echo "REMINDER: describe the new grids in madvfold/test/grids/README (settings in LOG.txt), then commit them"
